                    Game->StartScriptingEntity(Game->GetHero(), hero, SCRIPT_AI_PRIORITY_HIGHEST);
                    for (unsigned int i = 0; i < followers.size(); ++i) {
                        if (IsActiveThreadTerminating()) return;
                        hero.PerformExpression(followers[i], "EXPRESSION_WAIT");
