            if (G->Terminating()) return;
            if (G->recallPos.x * G->recallPos.x + G->recallPos.y * G->recallPos.y + G->recallPos.z * G->recallPos.z > 1e-12f) {
                if (G->Terminating()) return;
                ++G->teleToPos; ++G->facing;
